            // Continue with Native outputs only.
            engine::VmdBakeRig::from_model_path(
                &humanoid_source.model.model_source_id,
                &humanoid_source.model.model_path,
                &existing_skeletons,
            )
            .ok();
            // The rest of the import is intentionally not failed by an optional portable path.
            // Fall through via an empty portable output list.
