            // `continue` is unavailable because this is not a loop.
            // Use a local Option below instead.
            return send_vmd_native_only_after_humanoid_failure(
                &sender,
                project_path,
                source_id,
                source_path,
                model_paths,
                sub_assets,
                skeleton_records,
